CREATE TABLE productos(sku TEXT PRIMARY KEY, id_loyverse TEXT, variant_id TEXT, nombre TEXT, categoria TEXT, costo REAL, precio REAL, stock REAL, track_stock INT, barcode TEXT, sold_by_weight INT, updated_at TEXT, fecha_creacion TEXT, descripcion TEXT, imagen_url TEXT, proveedor_id INT, sector TEXT);
CREATE TABLE proveedores (id INTEGER PRIMARY KEY AUTOINCREMENT, nombre TEXT NOT NULL UNIQUE);
CREATE TABLE auditoria (id INTEGER PRIMARY KEY AUTOINCREMENT, fecha TEXT, accion TEXT, sku TEXT, producto TEXT, categoria TEXT, id_loyverse TEXT, stock REAL, motivo TEXT, responsable TEXT, cantidad REAL, vencimientos_id INTEGER);
CREATE TABLE carritos_guardados (provId TEXT PRIMARY KEY, provLabel TEXT, items TEXT NOT NULL, total REAL, fecha TEXT);
CREATE TABLE categoria_meta (categoria TEXT PRIMARY KEY, grupo_costo TEXT CHECK (grupo_costo IN ('COMPRAS','RRHH','OPERACIONAL','ADMINISTRATIVO','MARKETING','IMPUESTOS','FINANCIERO','OTRO')), seccion TEXT CHECK (seccion IN ('PERECIBLE','NO_PERECIBLE')), categoria_loyverse TEXT);
CREATE TABLE categorias_loyverse (id TEXT PRIMARY KEY, nombre TEXT);
CREATE TABLE clasificacion_abc (sku TEXT PRIMARY KEY, venta_total REAL, pct_participacion REAL, pct_acumulado REAL, clase TEXT, periodo_dias INTEGER, calculado_en TEXT);
CREATE TABLE clasificacion_pendiente (sku TEXT PRIMARY KEY REFERENCES productos(sku), motivo TEXT NOT NULL, fecha TEXT DEFAULT (datetime('now')));
CREATE TABLE config (clave TEXT PRIMARY KEY, valor TEXT);
CREATE TABLE config_costeo (id INTEGER PRIMARY KEY CHECK (id = 1), costo_fijo_default REAL NOT NULL DEFAULT 0, actualizado_en TEXT, exhib_watts REAL, exhib_kwh REAL, exhib_unidades_mes REAL);
CREATE TABLE config_costeo_producto (sku TEXT PRIMARY KEY, materia REAL, unidades REAL, minutos REAL, sueldo REAL, envase REAL, actualizado_en TEXT);
CREATE TABLE config_fiados (clave TEXT PRIMARY KEY, valor TEXT);
CREATE TABLE config_multiplo_producto (sku TEXT PRIMARY KEY, multiplo INTEGER NOT NULL, actualizado_en TEXT, empaque INTEGER, palabra TEXT);
CREATE TABLE config_vida_util (categoria TEXT PRIMARY KEY, dias_alerta INTEGER NOT NULL, tipo TEXT NOT NULL CHECK(tipo IN ('corta','larga','cambio')), nota TEXT);
CREATE TABLE configuracion (clave TEXT PRIMARY KEY, valor TEXT NOT NULL);
CREATE TABLE control_dedup (clave TEXT PRIMARY KEY);
CREATE TABLE control_procesados (archivo TEXT PRIMARY KEY, procesado_en TEXT NOT NULL DEFAULT (datetime('now')));
CREATE TABLE control_tx (ym TEXT PRIMARY KEY, n_transacciones INTEGER NOT NULL DEFAULT 0);
CREATE TABLE diccionario_aprendido (patron TEXT PRIMARY KEY, tipo TEXT NOT NULL, categoria TEXT NOT NULL, nombre TEXT NOT NULL, aprendido_en TEXT NOT NULL DEFAULT (datetime('now')));
CREATE TABLE facturas_calculos (id INTEGER PRIMARY KEY AUTOINCREMENT, factura_id TEXT NOT NULL, fecha TEXT NOT NULL, producto TEXT NOT NULL, costo_unitario REAL, margen REAL, precio_venta REAL, precio_psicologico REAL, categoria TEXT, responsable TEXT);
CREATE TABLE favoritos (sku TEXT PRIMARY KEY, fecha TEXT NOT NULL, responsable TEXT);
CREATE TABLE fiados (id INTEGER PRIMARY KEY AUTOINCREMENT, cliente_id TEXT, receipt_id_loyverse TEXT NOT NULL UNIQUE, monto_total REAL NOT NULL, estado TEXT NOT NULL DEFAULT 'abierto', fecha_hora TEXT NOT NULL);
CREATE TABLE fiados_lineas (id INTEGER PRIMARY KEY AUTOINCREMENT, fiado_id INTEGER NOT NULL REFERENCES fiados(id), sku TEXT NOT NULL, producto_nombre TEXT, cantidad REAL NOT NULL, precio_unitario REAL NOT NULL, receipt_line_item_id TEXT);
CREATE TABLE fiados_refunds_linea_manual (receipt_refund_numero TEXT PRIMARY KEY, fiado_id INTEGER NOT NULL, creado TEXT NOT NULL);
CREATE TABLE historial_precios (id INTEGER PRIMARY KEY AUTOINCREMENT, sku TEXT NOT NULL, fecha TEXT NOT NULL, precio_antes REAL, precio_despues REAL, costo_antes REAL, costo_despues REAL, responsable TEXT);
CREATE TABLE llegadas (id INTEGER PRIMARY KEY AUTOINCREMENT, fecha_deteccion TEXT, sku TEXT NOT NULL, producto TEXT, categoria TEXT, stock_antes REAL, stock_despues REAL, aumento REAL, estado TEXT, fecha_vencimiento_asignada TEXT, fecha_resolucion TEXT);
CREATE TABLE logs (id INTEGER PRIMARY KEY AUTOINCREMENT, fecha TEXT DEFAULT (datetime('now')), mensaje TEXT NOT NULL);
CREATE TABLE mermas (id INTEGER PRIMARY KEY AUTOINCREMENT, fecha TEXT, sku TEXT NOT NULL, producto TEXT, categoria TEXT, unidad TEXT, lote TEXT, cantidad REAL, costo_unitario REAL, costo_total REAL, motivo TEXT, estado_costo TEXT, responsable TEXT, origen TEXT);
CREATE TABLE movimientos_stock (id INTEGER PRIMARY KEY AUTOINCREMENT, sku TEXT NOT NULL, delta REAL NOT NULL, tipo TEXT NOT NULL, origen_id INTEGER, timestamp TEXT NOT NULL);
CREATE TABLE pagos_fiado (id INTEGER PRIMARY KEY AUTOINCREMENT, cliente_id TEXT, fiado_id INTEGER NOT NULL REFERENCES fiados(id), monto REAL NOT NULL, fecha_hora TEXT NOT NULL, metodo_pago TEXT NOT NULL, receipt_id_loyverse_abono TEXT NOT NULL, receipt_line_item_id_abono TEXT);
CREATE TABLE pedidos_pendientes (sku TEXT PRIMARY KEY REFERENCES productos(sku), barcode TEXT, nombre TEXT, proveedor TEXT, cantidad INTEGER, canal TEXT, fecha TEXT DEFAULT (datetime('now')), costo_unitario REAL DEFAULT 0, costo_total REAL DEFAULT 0, fecha_llegada_estimada TEXT, estado TEXT DEFAULT 'confirmado');
CREATE TABLE por_revisar (id INTEGER PRIMARY KEY AUTOINCREMENT, fecha TEXT, n_operacion TEXT, descripcion TEXT NOT NULL, monto INTEGER NOT NULL, motivo TEXT, archivo TEXT, creado_en TEXT NOT NULL DEFAULT (datetime('now')));
CREATE TABLE prestamos (id INTEGER PRIMARY KEY AUTOINCREMENT, fecha TEXT NOT NULL, sucursal TEXT NOT NULL, direccion TEXT NOT NULL, sku TEXT NOT NULL, producto TEXT, cantidad REAL NOT NULL, unidad TEXT, costo_unitario REAL, costo_total REAL, estado TEXT NOT NULL DEFAULT 'pendiente', fecha_devolucion TEXT, responsable TEXT, nota TEXT);
CREATE TABLE prestamos_dinero (id INTEGER PRIMARY KEY AUTOINCREMENT, fecha TEXT NOT NULL, sucursal TEXT NOT NULL, direccion TEXT NOT NULL, monto REAL NOT NULL, estado TEXT NOT NULL DEFAULT 'pendiente', fecha_cierre TEXT, responsable TEXT, nota TEXT);
CREATE TABLE prestamos_dinero_abonos (id INTEGER PRIMARY KEY AUTOINCREMENT, prestamo_id INTEGER NOT NULL REFERENCES prestamos_dinero(id), fecha TEXT NOT NULL, monto REAL NOT NULL, responsable TEXT);
CREATE TABLE producto_clasificacion_aprendida (patron TEXT PRIMARY KEY, proveedor_id INT, sector TEXT);
CREATE TABLE producto_proveedor_id (sku TEXT NOT NULL, proveedor_id INTEGER NOT NULL REFERENCES proveedores(id), PRIMARY KEY (sku, proveedor_id));
CREATE TABLE producto_proveedores (sku TEXT NOT NULL, proveedor TEXT NOT NULL, PRIMARY KEY(sku, proveedor));
CREATE TABLE push_subscriptions (endpoint TEXT PRIMARY KEY, p256dh TEXT, auth TEXT, creado TEXT);
CREATE TABLE registros (id INTEGER PRIMARY KEY AUTOINCREMENT, nombre TEXT NOT NULL, fecha TEXT NOT NULL, categoria TEXT NOT NULL, tipo TEXT NOT NULL CHECK (tipo IN ('INGRESO','COSTOS','GASTO OPE','MERMA','PLASTICOS','RETIRO_UTILIDAD','PRESTAMO','IMPUESTOS','INVERSION','TRASPASO_INTERNO')), cuenta TEXT NOT NULL CHECK (cuenta IN ('BANCO','EFECTIVO')), monto INTEGER NOT NULL, n_operacion TEXT NOT NULL UNIQUE, origen TEXT, subtipo_original TEXT, creado_en TEXT NOT NULL DEFAULT (datetime('now')), actualizado_en TEXT);
CREATE TABLE riesgo_excluidos (sku TEXT PRIMARY KEY, fecha TEXT NOT NULL, responsable TEXT);
CREATE TABLE sectores (id INTEGER PRIMARY KEY AUTOINCREMENT, nombre TEXT NOT NULL UNIQUE);
CREATE TABLE sectores_personalizados (nombre TEXT PRIMARY KEY);
CREATE TABLE variant_map (variant_id TEXT PRIMARY KEY, sku TEXT NOT NULL REFERENCES productos(sku));
CREATE TABLE vencimientos (id INTEGER PRIMARY KEY AUTOINCREMENT, fecha_ingreso TEXT, sku TEXT NOT NULL, producto TEXT, categoria TEXT, unidad TEXT, lote TEXT, cantidad REAL, fecha_vencimiento TEXT, estado TEXT, prioridad TEXT, accion TEXT, precio_recomendado REAL, costo_usado REAL, costo_origen TEXT, fecha_revision TEXT, revisado_por TEXT, motivo_cierre TEXT, fecha_retiro TEXT, merma_id INTEGER, monto_descuento REAL, descuento_activo INTEGER DEFAULT 0, precio_original REAL, precio_aplicado REAL, cant_vendida_desc REAL DEFAULT 0, cant_merma_desc REAL DEFAULT 0, fecha_descuento_aplicado TEXT);
CREATE TABLE ventas_diarias (id INTEGER PRIMARY KEY AUTOINCREMENT, fecha TEXT NOT NULL, sku TEXT NOT NULL, unidades REAL NOT NULL DEFAULT 0, venta REAL NOT NULL DEFAULT 0, utilidad REAL NOT NULL DEFAULT 0, UNIQUE(fecha, sku));
CREATE TABLE ventas_diarias_historico (fecha TEXT NOT NULL, sku TEXT NOT NULL, unidades REAL NOT NULL, venta INTEGER NOT NULL, utilidad INTEGER NOT NULL, PRIMARY KEY (fecha, sku));
CREATE TABLE ventas_recibos_detalle (receipt_number TEXT NOT NULL, sku TEXT NOT NULL, fecha TEXT NOT NULL, unidades REAL NOT NULL, venta REAL NOT NULL, utilidad REAL NOT NULL, PRIMARY KEY (receipt_number, sku));
CREATE INDEX idx_auditoria_fecha ON auditoria(fecha);
CREATE INDEX idx_auditoria_sku ON auditoria(sku);
CREATE INDEX idx_fiados_cliente ON fiados(cliente_id);
CREATE INDEX idx_fiados_estado ON fiados(estado);
CREATE INDEX idx_fiados_lineas_fiado ON fiados_lineas(fiado_id);
CREATE INDEX idx_historial_precios_sku ON historial_precios(sku);
CREATE INDEX idx_llegadas_estado ON llegadas(estado);
CREATE INDEX idx_llegadas_sku ON llegadas(sku);
CREATE INDEX idx_logs_fecha ON logs(fecha);
CREATE INDEX idx_mermas_fecha ON mermas(fecha);
CREATE INDEX idx_mermas_sku ON mermas(sku);
CREATE INDEX idx_movimientos_stock_sku ON movimientos_stock(sku);
CREATE INDEX idx_pagos_fiado_cliente ON pagos_fiado(cliente_id);
CREATE INDEX idx_pagos_fiado_fiado ON pagos_fiado(fiado_id);
CREATE INDEX idx_pedidos_pendientes_barcode ON pedidos_pendientes(barcode);
CREATE INDEX idx_porrevisar_fecha ON por_revisar(fecha);
CREATE INDEX idx_registros_categoria ON registros(categoria);
CREATE INDEX idx_registros_fecha ON registros(fecha);
CREATE INDEX idx_registros_tipo ON registros(tipo);
CREATE INDEX idx_vencimientos_estado ON vencimientos(estado);
CREATE INDEX idx_vencimientos_fecha_venc ON vencimientos(fecha_vencimiento);
CREATE INDEX idx_vencimientos_sku ON vencimientos(sku);
CREATE INDEX idx_ventas_fecha ON ventas_diarias(fecha);
CREATE INDEX idx_ventas_hist_sku_fecha ON ventas_diarias_historico(sku, fecha);
CREATE INDEX idx_ventas_sku_fecha ON ventas_diarias(sku, fecha);
CREATE VIEW vw_ventas_resumen AS SELECT sku, SUM(unidades) AS u_all, SUM(CASE WHEN fecha >= date('now','-7 day') THEN unidades ELSE 0 END) AS u7, SUM(CASE WHEN fecha >= date('now','-14 day') THEN unidades ELSE 0 END) AS u14, SUM(CASE WHEN fecha >= date('now','-30 day') THEN unidades ELSE 0 END) AS u30, SUM(CASE WHEN fecha >= date('now','-90 day') THEN unidades ELSE 0 END) AS u90, SUM(venta) AS rev, SUM(utilidad) AS prof FROM ventas_diarias GROUP BY sku;
